using System; using System.Text.RegularExpressions; class Program { static void Main() { var matn = "حَدَّثَنَا يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ قَالَ قَرَأْتُ عَلَى مَالِكٍ عَنْ ابْنِ شِهَابٍ عَنْ عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ"; var parts = Regex.Split(matn, @"(حَدَّثَنَا|حَدَّثَنِي|أَخْبَرَنَا|أَخْبَرَنِي|أَنْبَأَنَا|أَنَّهُ\s+سَمِعَ|أَنَّهَا\s+سَمِعَتْ|سَمِعْتُ|سَمِعَ|سَمِعَتْ|قَرَأْتُ\s+عَلَى|\bعَنْ\b)"); for(int i=0; i<parts.Length; i++) { Console.WriteLine($"[{i}]: '{parts[i]}'"); } } }
